    "G": { "name": "Magenta gef\xE4rbtes Glas", "color": "#b24cd8", "texture": "glass", "abbr": "Mg", "wiki": "Gef\xE4rbtes Glas", "raw": { "Sand": 1, "Magenta Farbstoff": 0.125 } },
    "v": { "name": "Bruchsteintreppe", "color": "#878787", "texture": "cobblestone", "shape": "stair", "dir": [0, 1], "wiki": "Treppe", "raw": { "Bruchstein": 1.5 } }
